  loadQuestions(data) {
    this.queslist = this.form.controls.form_questions as FormArray;
    const control = <FormArray>this.form.controls['form_questions'];
    for (let i = control.length - 1; i >= 0; i--) {
      control.removeAt(i)
    }
    if (data.length > 0) {
      for (let i = 0; i < data.length; i++) {
        this.queslist.push(this.fb.group({
          id: new FormControl(data[i].id, null),
          qid: new FormControl(data[i].qid, null),
          question: new FormControl(data[i].question, null),
          type: new FormControl(data[i].type, null),
          options: new FormControl(data[i].options, null),
          result: new FormControl(data[i].result, data[i].validation[0] == "required" ? Validators.required : null),
          subquestions: new FormControl(data[i].subquestions, null),
          min_result: new FormControl(data[i].min_result, null),
          validation: new FormControl(data[i].validation, null),
        }));

        if (data[i].type == 6) {
          this.imageKey = data[i].result;
          this.doc1Uploaded = true;
        }
      }

    }
  }

